// ==========================================================
// HEALTH CHECK
// ==========================================================

// Verifica que el backend responda HTTP 200.
pm.test('Health responde 200', function () {
    pm.response.to.have.status(200);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Verificamos que TechStore esté operativo.
pm.test('TechStore está disponible', function () {
    pm.expect(body.status).to.eql('ok');
});

// Verifica que el endpoint responda correctamente.
pm.test('Configuración responde 200', function () {
    pm.response.to.have.status(200);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Confirmamos que Bug Hunting realmente quedó desactivado.
pm.test('Bug Hunting está OFF', function () {
    pm.expect(body.bugs).to.eql(false);
});

// ==========================================================
// RESET DE DATOS
// ==========================================================
//
// Verificamos que el endpoint responda correctamente.
pm.test('Reset responde 200', function () {
    pm.response.to.have.status(200);
});
// Convertimos la respuesta del servidor a JSON.
const body = pm.response.json();
// Confirmamos que TechStore restauró su estado inicial.
pm.test('Datos reiniciados correctamente', function () {
    pm.expect(body.status).to.eql('reset');
});

// ==========================================================
// LOGIN ADMIN
// ==========================================================
// Verifica que el login responda correctamente.
pm.test('Login Admin responde 200', function () {
    pm.response.to.have.status(200);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Verificamos que exista un token.
pm.test('La respuesta contiene token', function () {
    pm.expect(body.token).to.be.a('string');
    pm.expect(body.token).to.not.be.empty;
});
// Verificamos que el usuario autenticado sea Admin.
pm.test('El rol autenticado es admin', function () {
    pm.expect(body.user.role).to.eql('admin');
});
// Guardamos el token para reutilizarlo
// en las siguientes pruebas API.
pm.environment.set(
    'adminToken',
    body.token
);

// ==========================================================
// LOGIN CUSTOMER
// ==========================================================
// Verifica que el login responda HTTP 200.
pm.test('Login Customer responde 200', function () {
    pm.response.to.have.status(200);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Verificamos que exista un token.
pm.test('La respuesta contiene token', function () {
    pm.expect(body.token).to.be.a('string');
    pm.expect(body.token).to.not.be.empty;
});
// Confirmamos que el usuario autenticado
// tenga rol Customer.
pm.test('El rol autenticado es customer', function () {
    pm.expect(body.user.role).to.eql('customer');
});
// Guardamos el token dentro del Environment activo
// para utilizarlo luego en pruebas de permisos.
pm.environment.set(
    'customerToken',
    body.token
);

// ==========================================================
// API-P01 - CREAR PRODUCTO VÁLIDO COMO ADMIN
// ==========================================================

// Verifica que el servidor cree correctamente el producto.
pm.test('API-P01 - responde 201', function () {
    pm.response.to.have.status(201);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Verificamos que el producto creado tenga un ID.
pm.test('El producto creado tiene ID', function () {
    pm.expect(body.id).to.be.a('number');
    pm.expect(body.id).to.be.above(0);
});
// Validamos los datos principales del producto.
pm.test('Los datos del producto son correctos', function () {
    pm.expect(body.name).to.eql('Producto API QA');
    pm.expect(body.price).to.eql(99.99);
    pm.expect(body.category).to.eql('Accesorios');
    pm.expect(body.stock).to.eql(25);
});
// Guardamos el ID para usarlo más adelante
// en las pruebas de edición y eliminación.
pm.environment.set(
    'createdProductId',
    body.id
);

// ==========================================================
// API-P02 - CREAR PRODUCTO INCOMPLETO
// ==========================================================
// El backend debe rechazar el producto
// porque falta un campo obligatorio.
pm.test('API-P02 - responde 400', function () {
    pm.response.to.have.status(400);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Verificamos que exista alguna respuesta de error.
//
// No forzamos todavía un texto exacto,
// porque primero queremos observar el contrato real del backend.
pm.test('La respuesta contiene información de error', function () {
    pm.expect(body).to.be.an('object');
});

// ==========================================================
// API-P03 - CUSTOMER NO PUEDE CREAR PRODUCTO
// ==========================================================
//
// Este caso valida autorización por rol.
// El usuario Customer está autenticado,
// pero no tiene permisos para crear productos.

pm.test('API-P03 - responde 403 Forbidden', function () {
    pm.response.to.have.status(403);
});


// Convertimos la respuesta a JSON
// para comprobar que el servidor devuelve
// una respuesta de error.
const body = pm.response.json();


// Verificamos que exista información de error.
// No exigimos todavía un texto exacto,
// porque primero validamos el contrato real.
pm.test('La respuesta contiene información de error', function () {
    pm.expect(body).to.be.an('object');
});

// ==========================================================
// API-P04 - EDITAR PRODUCTO
// ==========================================================

// Verifica que la actualización responda HTTP 200.
pm.test('API-P04 - responde 200', function () {
    pm.response.to.have.status(200);
});

// Convertimos la respuesta a JSON.
const body = pm.response.json();

// Verificamos que sea el producto que creamos anteriormente.
pm.test('Se actualiza el producto correcto', function () {
    pm.expect(body.id)
        .to.eql(
            Number(
                pm.environment.get('createdProductId')
            )
        );
});

// Verificamos que los nuevos valores hayan sido aplicados.
pm.test('Precio y stock fueron actualizados', function () {
    pm.expect(body.price).to.eql(149.99);
    pm.expect(body.stock).to.eql(40);
});

// ==========================================================
// API-P04.1 - VERIFICAR PERSISTENCIA
// ==========================================================

// El producto debe seguir existiendo.
pm.test('Consulta responde 200', function () {
    pm.response.to.have.status(200);
});
const body = pm.response.json();

// Confirmamos que los cambios realizados mediante PUT
// realmente quedaron almacenados en el backend.
pm.test('Los cambios persisten después del PUT', function () {
    pm.expect(body.price).to.eql(149.99);
    pm.expect(body.stock).to.eql(40);
});

// Confirmamos también el ID.
pm.test('Es el producto creado por la prueba', function () {
    pm.expect(body.id)
        .to.eql(
            Number(
                pm.environment.get('createdProductId')
            )
        );
});

// ==========================================================
// API-P05 - ELIMINAR PRODUCTO
// ==========================================================

// Verifica que la eliminación responda correctamente.
pm.test('API-P05 - responde 204', function () {
    pm.response.to.have.status(204);
});


// Guardamos el ID que estamos eliminando
// para poder comprobarlo después.
pm.environment.set(
    'deletedProductId',
    pm.environment.get('createdProductId')
);

// ==========================================================
// API-P05.1 - VERIFICAR ELIMINACIÓN
// ==========================================================

// El producto eliminado ya no debe existir.
pm.test('Producto eliminado devuelve 404', function () {
    pm.response.to.have.status(404);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Verificamos que el backend devuelva
// información de error.
pm.test('La respuesta contiene información de error', function () {
    pm.expect(body).to.be.an('object');
});

// ==========================================================
// API-S01 - BUSCAR PRODUCTOS CON "SMART"
// ==========================================================

// Verifica que la búsqueda responda correctamente.
pm.test('API-S01 - responde 200', function () {
    pm.response.to.have.status(200);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Verificamos que la respuesta sea una lista.
pm.test('La respuesta es una lista de productos', function () {
    pm.expect(body).to.be.an('array');
});
// Verificamos que la búsqueda encuentre resultados.
pm.test('La búsqueda devuelve productos', function () {
    pm.expect(body.length).to.be.above(0);
});
// Obtenemos los nombres de todos los productos encontrados.
const nombres = body.map(function (producto) {
    return producto.name;
});
// Verificamos que aparezcan productos relacionados
// con el término "smart".
pm.test('Encuentra Smartphone X12', function () {
    pm.expect(nombres).to.include('Smartphone X12');
});
pm.test('Encuentra Smartwatch Fit 3', function () {
    pm.expect(nombres).to.include('Smartwatch Fit 3');
});

// ==========================================================
// API-S02 - BUSCAR PRODUCTO INEXISTENTE
// ==========================================================

// Verifica que la búsqueda responda correctamente.
pm.test('API-S02 - responde 200', function () {
    pm.response.to.have.status(200);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// La API debe devolver una lista.
pm.test('La respuesta es una lista', function () {
    pm.expect(body).to.be.an('array');
});
// Como el término no existe,
// la lista debe estar vacía.
pm.test('La búsqueda no devuelve resultados', function () {
    pm.expect(body.length).to.eql(0);
});

// ==========================================================
// API-F01 - AGREGAR FAVORITO VÁLIDO
// ==========================================================

// Verifica que el favorito se agregue correctamente.
pm.test('API-F01 - responde 201', function () {
    pm.response.to.have.status(201);
});

// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Verificamos que la respuesta sea una lista
// o estructura válida relacionada con favoritos.
pm.test('La respuesta contiene datos de favoritos', function () {
    pm.expect(body).to.exist;
});
// Guardamos el ID del producto usado
// para reutilizarlo en los siguientes casos.
pm.environment.set(
    'favoriteProductId',
    2
);

// ==========================================================
// API-F02 - NO DUPLICAR FAVORITO
// ==========================================================
//
// El producto 2 ya fue agregado a favoritos en API-F01.
// Volvemos a enviarlo para comprobar que TechStore
// no cree una segunda copia del mismo favorito.
// La API acepta nuevamente la solicitud
// y responde HTTP 201.
pm.test('API-F02 - responde 201', function () {
    pm.response.to.have.status(201);
});
// Convertimos la respuesta a JSON.
// En este endpoint la respuesta es la lista de favoritos.
const body = pm.response.json();
// Verificamos que la respuesta sea una lista.
pm.test('La respuesta es una lista de favoritos', function () {
    pm.expect(body).to.be.an('array');
});
// Obtenemos el ID del producto que estamos probando.
const favoriteProductId = Number(
    pm.environment.get('favoriteProductId')
);
// Buscamos cuántas veces aparece ese producto
// dentro de la lista de favoritos.
const coincidencias = body.filter(function (producto) {
    return producto.id === favoriteProductId;
});
// El mismo producto debe aparecer UNA sola vez,
// aunque intentemos agregarlo nuevamente.
pm.test('El producto favorito no se duplica', function () {
    pm.expect(coincidencias.length).to.eql(1);
});

// ==========================================================
// API-F03 - NO AGREGAR PRODUCTO INEXISTENTE
// ==========================================================
//
// Intentamos agregar a favoritos un producto que no existe.
// Con Bug Hunting desactivado, la API debe rechazarlo.
// Verificamos que el servidor responda 404 Not Found.
pm.test('API-F03 - responde 404', function () {
    pm.response.to.have.status(404);
});
// Convertimos la respuesta a JSON.
const body = pm.response.json();
// Comprobamos que el backend devuelva
// información relacionada con el error.
pm.test('La respuesta contiene información de error', function () {
    pm.expect(body).to.be.an('object');
});
